SELECT
    ,
    lsi.stock_name,
    lwi.warehouse_name
FROM
    ord_wholesale_shipment ows
LEFT JOIN logc_stock_info lsi ON lsi.stock_code = ows.shipment_stock_code AND lsi.is_delete = 0 and lsi.biz_org_code = ows.biz_org_code
LEFT JOIN logc_warehouse_info lwi ON lwi.warehouse_code = ows.shipment_wrh AND lsi.warehouse_id = lwi.id AND lwi.is_delete = 0 and lwi.biz_org_code = ows.biz_org_code

    INNER JOIN ord_wholesale_shipment_detail sd on sd.wholesale_shipment_id = ows.id


    ows.is_delete = 0

        and ows.shipment_no = #{query.shipmentNo}


        and ows.shipment_status = #{query.shipmentStatus}


        and ows.client_code = #{query.clientCode}


        and ows.shipment_wrh = #{query.shipmentWrh}


        and ows.shipment_stock_code = #{query.shipmentStockCode}


        and ows.tracking_no = #{query.trackingNo}


        and ows.source_no = #{query.sourceNo}


        and ows.biz_org_code = #{query.bizOrgCode}


        and ows.create_time >= #{query.beginCreateTime}


        and ows.create_time <= #{query.endCreateTime}


        and ows.delivery_time >= #{query.deliveryTimeBegin}


        and ows.delivery_time <= #{query.deliveryTimeEnd}


        and ows.is_reversal_order = #{query.isReversalOrder}


        and ows.is_reversal = #{query.isReversal}


        and ows.id in

            #{wholesaleShipmentId}



        and ows.distribution_type = #{query.distributionType}


        and ows.creator like CONCAT('%',#{query.creator},'%')


        and sd.goods_code = #{query.goodsCode}


        and ows.push_pur_time between #{query.pushPurTimeBegin} and #{query.pushPurTimeEnd}


ORDER BY ows.create_time DESC,ows.id DESC

SELECT lsi.id AS stockId, lsi.stock_code, lsi.stock_name, lsi.warehouse_id, lsi.biz_org_code FROM logc_stock_info lsi INNER JOIN logc_stock_business_switch lsbs ON lsbs.stock_code = lsi.stock_code and lsi.biz_org_code = lsbs.biz_org_code and lsbs.${isOutReturn}
lsi.is_delete = 0
and (lsi.biz_org_code = #{bizOrgCode} or lsi.id in (select stock_id from logc_stock_org_auth where biz_org_code = #{bizOrgCode}))
and lsi.is_enable = #{isEnable}

SELECT owrd.id, owrd.goods_code, owrd.wholesale_shipment_id FROM ord_wholesale_shipment_detail owrd INNER JOIN ord_wholesale_shipment ows on ows.id = owrd.wholesale_shipment_id and ows.is_delete = 0
owrd.is_delete = 0
and owrd.goods_code = #{goodsCode}
and ows.shipment_status = #{status}
and ows.biz_org_code = #{bizOrgCode}

SELECT
sum(ows.application_quantity) as applicationQuantity, sum(ows.application_amount) as applicationAmount,
sum(ows.shipment_quantity) as shipmentQuantity,sum(ows.practical_shipment_amount) as practicalShipmentAmount
FROM
ord_wholesale_shipment ows
LEFT JOIN logc_stock_info lsi ON lsi.stock_code = ows.shipment_stock_code AND lsi.is_delete = 0 and lsi.biz_org_code = ows.biz_org_code
LEFT JOIN logc_warehouse_info lwi ON lwi.warehouse_code = ows.shipment_wrh AND lsi.warehouse_id = lwi.id AND lwi.is_delete = 0 and lwi.biz_org_code = ows.biz_org_code

    ows.is_delete = 0

        and ows.shipment_no = #{query.shipmentNo}


        and ows.shipment_status = #{query.shipmentStatus}


        and ows.client_code = #{query.clientCode}


        and ows.shipment_wrh = #{query.shipmentWrh}


        and ows.shipment_stock_code = #{query.shipmentStockCode}


        and ows.biz_org_code = #{query.bizOrgCode}


        and ows.create_time >= #{query.beginCreateTime}


        and ows.create_time <= #{query.endCreateTime}


        and ows.delivery_time >= #{query.deliveryTimeBegin}


        and ows.delivery_time <= #{query.deliveryTimeEnd}


        and ows.is_reversal_order = #{query.isReversalOrder}


        and ows.is_reversal = #{query.isReversal}


        and ows.id in

            #{wholesaleShipmentId}



ORDER BY ows.create_time DESC,ows.id DESC

