update ord_wholesale_shipment ws left join ord_wholesale_shipment_detail wsd on ws.id = wsd.wholesale_shipment_id
    set ws.push_pur_progress = #{obj.pushPurProgress},ws.updater = #{updater},ws.update_time = #{updateTime}
where wsd.vendor_code = #{obj.vendorCode} and ws.pur_batch_number = #{obj.purBatchNumber} and ws.biz_org_code = #{obj.bizOrgCode} and wsd.is_delete = 0 and ws.is_delete = 0
